def compute(vars):
    flight_attendants = vars["v1"]
    pilots = vars["v2"]

    if pilots == 0:
        return None

    ratio = flight_attendants / pilots

    return {
        "value": ratio,
        "trace": {
            "flight_attendants": flight_attendants,
            "pilots": pilots,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
